    Console.WriteLine("---");
}

Console.WriteLine();
Console.WriteLine("=== PROJECT BUILD RESULTS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    if (p.FindChildrenRecursive<Error>().Any())
    {
        Console.WriteLine($"FAILED: {p.Name} (TargetFramework: {p.TargetFramework})");
        var deps = p.FindChildrenRecursive<Project>();
        if (deps.Any())
        {
            Console.WriteLine($"  Dependencies: {string.Join(", ", deps.Select(d => d.Name))}");
        }
    }
}

Console.WriteLine();
Console.WriteLine("=== WARNINGS (first 20) ===");
foreach (var w in warnings.Take(20))
{
    var project = w.GetNearestParent<Project>();
    Console.WriteLine($"[{w.Code}] {project?.Name}: {w.Text}");
}
