cat > /tmp/binlog-reader/Program.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Check project dependency chain
var projects = build.FindChildrenRecursive<Project>();
Console.WriteLine("=== ALL PROJECTS ===");
foreach (var p in projects.Where(p => p.Name.EndsWith(".csproj")))
{
    var succeeded = !p.FindChildrenRecursive<Error>().Any();
    Console.WriteLine($"{(succeeded ? "OK" : "FAIL")}: {p.Name} (TFM: {p.TargetFramework})");

    // Check project references
    var items = p.FindChildrenRecursive<AddItem>().Where(a => a.Name == "ProjectReference");
    foreach (var item in items)
    {
        foreach (var child in item.Children)
            Console.WriteLine($"  -> ProjectRef: {child}");
    }
}

// Check if Api.csproj failed
Console.WriteLine();
Console.WriteLine("=== Api.csproj RESULT ===");
foreach (var p in projects.Where(p => p.Name == "Api.csproj"))
{
    var errs = p.FindChildrenRecursive<Error>();
    Console.WriteLine($"Errors in Api.csproj: {errs.Count}");
    var msgs = p.FindChildrenRecursive<Message>().Where(m => m.Text != null && (m.Text.Contains("error") || m.Text.Contains("failed")));
    foreach (var m in msgs.Take(10))
        Console.WriteLine($"  MSG: {m.Text}");
}

// Look for dependency build failures in the solution build
Console.WriteLine();
Console.WriteLine("=== SOLUTION BUILD MESSAGES ===");
foreach (var p in projects.Where(p => p.Name == "BuildDiag.sln"))
{
    var msgs = p.FindChildrenRecursive<Message>().Where(m => m.Text != null && m.Text.Contains("fail"));
    foreach (var m in msgs.Take(10))
        Console.WriteLine($"  MSG: {m.Text}");
}

// Check NuGet restore
Console.WriteLine();
Console.WriteLine("=== NUGET RESTORE ISSUES ===");
var restoreErrors = build.FindChildrenRecursive<Error>().Where(e => e.Code != null && e.Code.StartsWith("NU"));
foreach (var e in restoreErrors)
    Console.WriteLine($"  [{e.Code}] {e.Text}");

var restoreWarnings = build.FindChildrenRecursive<Warning>().Where(w => w.Code != null && w.Code.StartsWith("NU"));
foreach (var w in restoreWarnings)
    Console.WriteLine($"  [{w.Code}] {w.Text}");

// Check the Services.csproj package references
Console.WriteLine();
Console.WriteLine("=== PACKAGE REFERENCES ===");
foreach (var p in projects.Where(p => p.Name == "Services.csproj"))
{
    var pkgRefs = p.FindChildrenRecursive<AddItem>().Where(a => a.Name == "PackageReference");
    foreach (var item in pkgRefs)
        foreach (var child in item.Children)
            Console.WriteLine($"  Services.csproj PackageRef: {child}");

    var resolvedRefs = p.FindChildrenRecursive<AddItem>().Where(a => a.Name == "Reference");
    foreach (var item in resolvedRefs)
        foreach (var child in item.Children)
            Console.WriteLine($"  Services.csproj Ref: {child}");
}
